12	func runAggregate(t *testing.T, input string, window int64) (string, string, error) {
13		t.Helper()
14		var stdout, stderr bytes.Buffer
15		err := RunAggregate(strings.NewReader(input), window, &stdout, &stderr)
16		return stdout.String(), stderr.String(), err
17	}
18	
19	func TestAggregateBasicClosureAndOrder(t *testing.T) {
20		input := strings.Join([]string{
21			`{"type":"event","key":"sensor-b","time":800,"value":-2}`,
22			`{"type":"event","key":"sensor-a","time":1200,"value":5}`,
23			``, // blank line must be ignored
24			`{"type":"event","key":"sensor-a","time":1500,"value":7}`,
