func (s *aggregateState) processWatermark(obj map[string]json.RawMessage, lineNo int) error {
	next, err := requiredNonNegInt64(obj, "time", lineNo)
	if err != nil {
		return err
	}
	p, err := s.requiredPartition(obj, lineNo)
	if err != nil {
		return err
	}

	if s.partitions == 0 {
		if s.watermark != nil && next < *s.watermark {
			return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark moved backwards from %d to %d", *s.watermark, next)}
		}
		s.watermark = &next
	} else {
		if s.partWatermark[p] != nil && next < *s.partWatermark[p] {
			return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark for partition %d moved backwards from %d to %d", p, *s.partWatermark[p], next)}
		}
		s.partWatermark[p] = &next
		s.watermark = s.effectiveWatermark()
	}

	if s.watermark == nil {
		return nil
	}
	return s.closeWindows(*s.watermark)
}

// effectiveWatermark returns the minimum per-partition watermark once every
// partition has reported at least one, or nil otherwise.
func (s *aggregateState) effectiveWatermark() *int64 {
	var min int64
	for i, w := range s.partWatermark {
		if w == nil {
			return nil
		}
		if i == 0 || *w < min {
			min = *w
		}
	}
	return &min
